actions.script:
def access=ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess')
    .parameters([sessionId:sessionId,transactionId:transactionId]).call()
if (!access?.allowed) return
def txn=ec.entity.find('zenith.erp.pos.PosTransaction').condition('transactionId',transactionId).forUpdate(true).one()
def session=ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',sessionId).one()
if (txn.sessionId!=sessionId || session.statusId!='PsOpen' || txn.statusId!='PtCreated' || txn.transactionNumber) {
    ec.message.addError('Only the open, unissued cart in this session can be cleared.'); return
}
if (ec.entity.find('zenith.erp.pos.PosPayment').condition('transactionId',transactionId).count()) {
    ec.message.addError('This cart has recorded payments. Resolve the payments before clearing it.'); return
}
ec.entity.find('zenith.erp.pos.PosItemPriceOverride').condition('transactionId',transactionId).deleteAll()
ec.entity.find('zenith.erp.pos.PosTransactionItem').condition('transactionId',transactionId).deleteAll()
ec.entity.find('zenith.erp.tax.TaxLineDetail').condition('referenceType','PosTransactionItem').condition('referenceId',transactionId).deleteAll()
ec.service.sync().name('zenith.pos.PosServices.recalculate#TransactionTotals').parameter('transactionId',transactionId).call()
ec.service.sync().name('update#zenith.erp.pos.PosSession').parameters([sessionId:sessionId,lastActivityDate:ec.user.nowTimestamp]).call()

stock=[:]
def access=ec.service.sync().name('zenith.pos.PosAccessServices.assert#PosAccess').parameter('sessionId',sessionId).call()
if (!access?.allowed) return
def ids=productIds.findAll { it instanceof String && it.length()<=40 }.unique().take(120)
if (!ids) return
def session=ec.entity.find('zenith.erp.pos.PosSession').condition('sessionId',sessionId).one()
def terminal=ec.entity.find('zenith.erp.pos.PosTerminal').condition('terminalId',session.terminalId).one()
def facility=terminal.facilityId ? ec.entity.find('mantle.facility.Facility').condition('facilityId',terminal.facilityId).one() : null
def products=ec.entity.find('mantle.product.Product').condition('ownerPartyId',access.organizationPartyId)
    .condition('productId','in',ids).list()
products.each { p -> stock[p.productId]=[tracked:p.inventoryTracked=='Y',quantity:null] }
if (!facility || facility.ownerPartyId!=access.organizationPartyId) return
def tracked=products.findAll { it.inventoryTracked=='Y' }*.productId
tracked.each { id -> stock[id].quantity=BigDecimal.ZERO }
if (!tracked) return
ec.entity.find('mantle.product.asset.Asset').condition('ownerPartyId',access.organizationPartyId)
    .condition('facilityId',facility.facilityId).condition('assetTypeEnumId','AstTpInventory')
    .condition('productId','in',tracked).selectFields(['productId','quantityOnHandTotal']).list().each { a ->
        stock[a.productId].quantity+=((a.quantityOnHandTotal ?: 0) as BigDecimal)
    }

products=[]
def org=ec.service.sync().name('zenith.barcode.BarcodeServices.get#AuthorizedActiveOrganization').call().activeOrgId
def query=(term ?: '').toString().replaceAll(/\s+/, ' ').replaceAll(/^ +/, '')
if (!org || !query.trim()) return
def start=Math.max(0, Math.min(offset ?: 0, 3000))
def size=Math.max(1, Math.min(pageSize ?: 60, 61))
def cf=ec.entity.conditionFactory; def EC=org.moqui.entity.EntityCondition
def escaped=query.replace('\\','\\\\').replace('%','\\%').replace('_','\\_')
def like='%'+escaped+'%'
def codes=ec.service.sync().name('zenith.barcode.BarcodeServices.get#ScanAliases').parameters([code:query.trim()]).call().aliases
def aliases=ec.entity.find('zenith.erp.barcode.ProductBarcode').condition('organizationPartyId',org).condition('isActive','Y')
    .condition(cf.makeCondition([cf.makeCondition('barcodeValue',EC.LIKE,like).ignoreCase(),cf.makeCondition('barcodeValue',EC.IN,codes)],EC.OR)).list()*.productId
def matches=['productName','pseudoId','productId'].collect { cf.makeCondition(it,EC.LIKE,like).ignoreCase() }
if (aliases) matches.add(cf.makeCondition('productId',EC.IN,aliases))
def prefix=cf.makeCondition('productName',EC.LIKE,escaped+'%').ignoreCase()
def others=cf.makeCondition([cf.makeCondition('productName',EC.NOT_LIKE,escaped+'%').ignoreCase(),cf.makeCondition('productName',EC.EQUALS,null)],EC.OR)
def find={ ec.entity.find('mantle.product.Product').condition('ownerPartyId',org).condition('productTypeEnumId','PtAsset')
    .condition(cf.makeCondition(matches,EC.OR)).orderBy('productName,productId') }
def firstCount=find().condition(prefix).count()
if (start < firstCount) products.addAll(find().condition(prefix).offset(start).limit(size).list())
if (products.size() < size) products.addAll(find().condition(others).offset(Math.max(0,start-firstCount) as int).limit(size-products.size()).list())

def posOrg=access.organizationPartyId
gridProducts = []
// Limit the first screen's cards and per-product price lookups; "Load more" keeps the rest available.
gridPageSize = 60
def rawOffset = (productOffset ?: '0').toString()
gridOffset = rawOffset ==~ /[0-9]{1,4}/ ? Math.min(rawOffset.toInteger(), 3000) : 0
gridHasMore = false
if (searchTerm) {
    gridProducts = ec.service.sync().name('zenith.pos.PosCheckoutServices.search#PosProducts')
        .parameters([term:searchTerm,offset:gridOffset,pageSize:gridPageSize+1]).call().products ?: []
} else if (catId) {
    def category = ec.entity.find('mantle.product.category.ProductCategory')
        .condition('productCategoryId',catId).condition('ownerPartyId',posOrg).one()
    def members = category ? ec.entity.find("mantle.product.category.ProductCategoryMember")
        .condition("productCategoryId", catId)
        .conditionDate("fromDate", "thruDate", ec.user.nowTimestamp)
        .orderBy("sequenceNum,productId").list() : []
    def pIds = members.collect { it.productId }
    if (pIds) {
        gridProducts = ec.entity.find("mantle.product.Product")
            .condition("productId", org.moqui.entity.EntityCondition.ComparisonOperator.IN, pIds)
            .condition([ownerPartyId: posOrg, productTypeEnumId: 'PtAsset'])
            .offset(gridOffset).limit(gridPageSize + 1).orderBy("productName,productId").list()
    }
} else {
    gridProducts = ec.entity.find("mantle.product.Product")
        .condition([productTypeEnumId:'PtAsset', ownerPartyId: posOrg])
        .offset(gridOffset).limit(gridPageSize + 1).orderBy("productName,productId").list()
}
if (gridProducts.size() > gridPageSize) {
    gridHasMore = true
    gridProducts = gridProducts.subList(0, gridPageSize)
}
gridNextOffset = gridOffset + gridProducts.size()
gridCardStock=[:]
if (sessionId && gridProducts) gridCardStock=ec.service.sync().name('zenith.pos.PosCheckoutServices.get#PosCardStock')
    .parameters([sessionId:sessionId,productIds:gridProducts*.productId]).call().stock ?: [:]

// Show the live Pricing-module price on grid cards when this shop uses price lists (else the product MRP).
// No-op (one count query) for shops without price lists, so the POS stays fast and unchanged.
def _hasPL = ec.entity.find("zenith.erp.pricing.PriceList").condition("organizationPartyId", posOrg).condition("priceListTypeEnumId","PltSelling").count() != 0
if (_hasPL && gridProducts) {
    for (gp in gridProducts) {
        try {
            def _pr = ec.service.sync().name("zenith.pricing.PricingServices.calculate#Price").parameters([productId:gp.productId, quantity:1, organizationPartyId:posOrg, salesChannelEnumId:"ScPos"]).call()
            if (_pr?.unitPrice != null && (_pr.unitPrice as BigDecimal).signum() == 1) gp.mrpAmount = _pr.unitPrice
        } catch (Throwable e) { }
    }
}
